'use strict';
(()=>{
const root=document.getElementById('lab'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const E=LabEngine,storageKey='atlas-interview-v1';
let state=null,tool='desktop',query='',selected=null,folder='',recordType='',timeRange='all',sortKey='time',sortDirection=-1,startOpen=false,scanReady=false,atlasView='scan',storageOK=true,timer,toastTimer;
const toolGlyph=id=>id==='journaltrace'?`<svg class="app-original-icon generic-app-icon" viewBox="0 0 32 32" aria-hidden="true"><rect x="3" y="5" width="26" height="23" rx="2" fill="#e8edf4" stroke="#8794a2"/><path d="M4 11h24V6H4z" fill="#6a98c6"/><path d="M8 16h7v7H8zM18 16h6M18 20h6" fill="none" stroke="#8194aa" stroke-width="2"/></svg>`:['everything','journal','journaltrace','downloads','history','activity','prefetch','usb','atlas'].includes(id)?`<img class="app-original-icon" src="icons/${id}.png" alt="">`:`<span class="tool-glyph explorer">▤</span>`;
try{const s=JSON.parse(sessionStorage.getItem(storageKey)||'null');if(s?.session?.version===2&&Array.isArray(s.session.artifacts)&&s.notes&&typeof s.notes==='object')state=s;}catch{storageOK=false;}
function save(){try{sessionStorage.setItem(storageKey,JSON.stringify(state));}catch{storageOK=false;} }
function toast(text){const el=document.getElementById('lab-toast');el.textContent=text;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,3000);}
const time=s=>new Date(s).toLocaleString('tr-TR',{hour:'2-digit',minute:'2-digit',second:'2-digit',day:'2-digit',month:'2-digit'});
function welcome(){root.innerHTML=`<main class="welcome"><a class="back-link" href="../#home" target="_top">← AAC Wiki</a><div class="welcome-grid"><section><span class="eyebrow">ATLAS · UYGULAMALI MÜLAKAT</span><h1>İzleri takip et.<br><span>Kararını kanıtla.</span></h1><p class="lead">Her oturumda farklı bir oyuncu, farklı dosyalar ve yeni bir kayıt zinciri. Hazır cevabı seçmek yerine kontrolü sen yap.</p><div class="welcome-actions"><button class="primary" data-action="new">Yeni mülakat başlat <span>↗</span></button>${state?`<button class="secondary" data-action="resume">${state.finished?'Son değerlendirmeyi aç':'Kaldığım yerden devam et'}</button>`:''}</div><p class="case-bank-note"><strong>${E.catalogue.length} vaka</strong> · ${E.families.length} istemci / eklenti ailesi · ${E.patterns.length} farklı kanıt akışı</p><p class="lab-disclosure">Tarayıcıda çalışan eğitim simülasyonu. Gerçek Windows’a veya bir oyuncunun bilgisayarına bağlanmaz; örnek dosya ve kayıtlar bu oturum için üretilir.</p></section><aside class="preview"><div class="preview-top"><i></i><i></i><i></i><span>ATLAS KONTROL LABORATUVARI</span></div><div class="preview-body"><div class="preview-mark"><img src="logo.png?v=original3" alt="Atlas Lab"></div><h2>Dosya adının arkasına bak.</h2><p>İçerik → sistem kaydı → kanıt → değerlendirme</p><div class="preview-tools"><span>Everything</span><span>Journal</span><span>Mod içeriği</span><span>AtlasAC</span></div></div><div class="preview-footer"><span>${E.catalogue.length} farklı vaka</span><span>100 puan değerlendirme</span></div></aside></div><div class="intro-steps"><article><b>01</b><h3>Ortamı incele</h3><p>Aktif profili, dosyaları, arşivleri ve sistem kayıtlarını karşılaştır.</p></article><article><b>02</b><h3>Kanıtını topla</h3><p>İlgili satırları kanıt defterine ekle. Mevcut dosya ile silinmiş izi ayır.</p></article><article><b>03</b><h3>Sonucunu gör</h3><p>Bitirdiğinde doğru tespitleri, kaçırdığın izleri ve yanlış işaretlemeleri gör.</p></article></div><p class="privacy-note">Her sekme ayrı bir oturumdur; aynı anda farklı kişiler bağımsız kullanabilir. İlerleme yalnız bu sekmede saklanır. Bu alan alıştırma içindir; gözetimli, gizli cevap anahtarlı resmî sınav sistemi değildir.</p></main>`;}
function create(){const seed=crypto.getRandomValues(new Uint32Array(1))[0],previous=state?.session?.caseIds||[];state={session:E.create(seed,Date.now(),null,previous),notes:{},finished:false,selected:null};tool='desktop';query='';folder='';recordType='';timeRange='all';selected=null;scanReady=false;scanRunning=false;atlasCategory='findings';journalPage=1;journalFilters.clear();save();render();}
function elapsed(){return Math.max(0,Math.floor((Date.now()-state.session.startedAt)/1000));}
function timerText(){const remaining=Math.max(0,state.session.limit-elapsed());return Math.floor(remaining/60).toString().padStart(2,'0')+':'+(remaining%60).toString().padStart(2,'0');}
function note(a){return state.notes[a]||(state.notes[a]={evidence:[],verdict:'',usage:'',comment:''});}
function nativeSortValue(r,key){const a=state.session.artifacts.find(a=>a.id===r.artifact);return key==='name'?a?.name||r.name||r.action:key==='folder'?a?.folder||'':key==='path'?a?.path||'':key==='browser'?'Microsoft Edge':key==='user'?state.session.user:r[key]||r.detail;}
function visibleRows(){let list=E.rows(state.session,tool,query);if(recordType)list=list.filter(r=>r.action===recordType);if(timeRange!=='all'){const after=state.session.startedAt-Number(timeRange)*3600000;list=list.filter(r=>new Date(r.time).getTime()>=after);}list.sort((a,b)=>sortKey==='size'?(parseFloat(state.session.artifacts.find(x=>x.id===a.artifact)?.size||0)-parseFloat(state.session.artifacts.find(x=>x.id===b.artifact)?.size||0))*sortDirection:String(nativeSortValue(a,sortKey)).localeCompare(String(nativeSortValue(b,sortKey)),'tr')*sortDirection);if((tool==='explorer'||tool==='everything')&&!showHidden)list=list.filter(r=>!state.session.artifacts.find(a=>a.id===r.artifact)?.hidden);if(tool==='explorer'&&folder)list=list.filter(r=>state.session.artifacts.find(a=>a.id===r.artifact)?.folder===folder);return list;}
function toolNav(){return Object.entries(E.tools).map(([id,label])=>`<button class="tool-button ${tool===id?'active':''}" data-tool="${id}" title="${label}">${toolGlyph(id)}<span>${label}</span></button>`).join('');}
const windows=new Map();let windowSession='',zIndex=20,activeWindow=null,showHidden=true,journalFilters=new Set(),journalPage=1;
const folderIcon=`<svg class="folder-icon" viewBox="0 0 48 40" aria-hidden="true"><path fill="#e7a832" d="M2 7a3 3 0 0 1 3-3h15l5 5h18a3 3 0 0 1 3 3v22H2z"/><path fill="#ffcf59" d="M2 13h44v21a3 3 0 0 1-3 3H5a3 3 0 0 1-3-3z"/></svg>`;
function storeWindow(){if(activeWindow&&windows.has(activeWindow))Object.assign(windows.get(activeWindow),{query,selected,folder,recordType,timeRange,sortKey,sortDirection,atlasView});}
function focusWindow(id){storeWindow();const w=windows.get(id);if(!w)return;activeWindow=id;tool=id;({query,selected,folder,recordType,timeRange,sortKey,sortDirection,atlasView}=w);document.querySelectorAll('.app-window').forEach(el=>{el.classList.toggle('window-active',el===w.el);el.querySelector('[id="app-body"]')?.removeAttribute('id');});w.el.hidden=false;w.el.style.zIndex=++zIndex;w.el.querySelector('.app-content').id='app-body';renderTaskbar();}
function openWindow(id){if(!state||state.finished)return;if(windows.has(id)){focusWindow(id);renderApp();renderNotes();return;}storeWindow();const el=document.createElement('section');el.className='app-window '+(id==='atlas'?'atlas-native':id==='journal'?'journal-native':'classic-native');el.dataset.window=id;el.setAttribute('aria-label',E.tools[id]);const offset=windows.size%5*28;el.style.cssText=`left:${Math.min(140+offset,innerWidth*.15)}px;top:${42+offset}px;width:${Math.min(1080,innerWidth-90)}px;height:${Math.min(720,innerHeight-110)}px;z-index:${++zIndex}`;
el.innerHTML=`<header class="window-title">${toolGlyph(id)}<strong>${id==='journal'?'Easy Journal Viewer':E.tools[id]}</strong><div class="window-buttons"><button data-action="minimize-window" aria-label="Pencereyi küçült">—</button><button data-action="maximize-window" aria-label="Pencereyi büyüt veya geri yükle">□</button><button data-action="close-window" aria-label="Pencereyi kapat">✕</button></div></header><div class="native-menubar">${(id==='everything'?['File','Edit','View','Search','Bookmarks','Tools','Help']:['File','Edit','View','Options','Help']).map(x=>`<button data-native-menu="${x}">${x}</button>`).join('')}</div><div class="app-content"></div><footer class="native-status"><span>Hazır</span><span>${id==='everything'?'Everything 1.4 · NTFS':E.tools[id]} · Eğitim</span></footer><div class="resize-grip" aria-hidden="true"></div>`;
const w={el,query:'',selected:null,folder:'',recordType:'',timeRange:'all',sortKey:'time',sortDirection:-1,atlasView:'scan'};windows.set(id,w);document.getElementById('window-layer').append(el);focusWindow(id);renderApp();renderNotes();}
function renderTaskbar(){const h=document.getElementById('task-apps');if(!h)return;h.innerHTML=[...new Set(['explorer','everything','atlas',...windows.keys()])].map(id=>`<button data-tool="${id}" title="${E.tools[id]}" class="task-app ${windows.has(id)?'running':''} ${activeWindow===id&&!windows.get(id)?.el.hidden?'focused':''}">${toolGlyph(id)}</button>`).join('');}
function toggleNotes(show=true){document.querySelector('.notebook')?.classList.toggle('show',show);if(show)renderNotes();}
function render(){clearInterval(timer);if(!state){welcome();return;}if(state.finished){document.body.classList.remove('windows-mode');results();return;}const s=state.session;document.body.classList.add('windows-mode');if(windowSession===s.id&&document.getElementById('window-layer')){if(tool!=='desktop')openWindow(tool);return;}windows.clear();activeWindow=null;windowSession=s.id;
root.innerHTML=`<main class="workspace windows-desktop"><section class="desk" aria-label="Windows eğitim masaüstü"><div class="desktop-shortcuts"><button data-action="apps-folder">${folderIcon}<span>AAC Uygulamalar</span></button><button data-action="brief">${folderIcon}<span>AAC Senaryo</span></button><button data-action="notes">${folderIcon}<span>AAC Bulgular</span></button>${['explorer','everything','journal','atlas'].map(id=>`<button data-tool="${id}">${id==='explorer'?folderIcon:toolGlyph(id)}<span>${E.tools[id]}</span></button>`).join('')}<button data-action="run"><span class="run-icon">▣</span><span>Çalıştır</span></button></div><div class="desktop-watermark"><img src="logo.png?v=original3" alt="Atlas"><small>${esc(s.nick)} · ${s.id}</small><span>Kontrol eğitimi</span></div><div id="window-layer"></div><div class="session-overlay"><span>${esc(s.nick)} · ${esc(s.launcher)}</span><code>${esc(s.game)}</code></div><div class="start-menu" hidden><input id="start-search" placeholder="Uygulama veya ayar ara" aria-label="Başlat menüsünde ara"><h3>Sabitlenmiş</h3><div class="start-apps">${toolNav()}</div><footer><span>◉ ${esc(s.user)}</span><button data-action="finish-prompt">Mülakatı bitir ⏻</button></footer></div></section><aside class="notebook" id="notebook"><header><div><span class="eyebrow">AAC BULGULAR</span><h2>Kanıt defteri</h2></div><button class="text-button notes-close" data-action="notes-close" aria-label="Kanıt defterini kapat">✕</button></header><p class="notebook-intro">Bulgularını kaynaklarıyla birlikte kaydet.</p><div id="note-body"></div></aside><footer class="windows-taskbar"><div class="taskbar-left"><a href="../#home" target="_top" title="AAC Wiki"><img src="logo.png?v=original3" alt="AAC Wiki"></a><span class="simulation-badge">EĞİTİM</span></div><div class="taskbar-center"><button data-action="start-menu" class="windows-start" aria-label="Başlat" aria-expanded="false"><svg viewBox="0 0 24 24"><path fill="#50b9ff" d="M1 1h10v10H1zM13 1h10v10H13zM1 13h10v10H1zM13 13h10v10H13z"/></svg></button><button data-action="run" class="task-search" title="Çalıştır (Win + R)">⌕</button><div id="task-apps"></div></div><div class="taskbar-tray"><button data-action="notes" title="Kanıt defteri">▤</button><button data-action="brief" title="Görev ve oyuncu bilgisi">ⓘ</button><button data-action="fullscreen" title="Tam ekran">⛶</button><span id="lab-time" class="timer">${timerText()}</span><time id="windows-clock"></time><button data-action="desktop" class="show-desktop" aria-label="Masaüstünü göster"></button></div></footer></main>`;renderTaskbar();renderNotes();const tick=()=>{const el=document.getElementById('lab-time');if(el)el.textContent=timerText();const clock=document.getElementById('windows-clock');if(clock)clock.innerHTML=new Date().toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit'})+'<br>'+new Date().toLocaleDateString('tr-TR');};tick();timer=setInterval(tick,1000);}
function setupColumns(body){const w=windows.get(tool);if(!w)return;body.querySelectorAll('th').forEach((th,index)=>{if(w.columns?.[index]){th.style.width=w.columns[index]+'px';th.style.minWidth=w.columns[index]+'px';}const grip=document.createElement('span');grip.className='column-resizer';grip.setAttribute('aria-hidden','true');grip.onpointerdown=e=>{e.preventDefault();e.stopPropagation();const x=e.clientX,width=th.getBoundingClientRect().width;grip.setPointerCapture(e.pointerId);const move=ev=>{const px=Math.max(50,width+ev.clientX-x);th.style.width=px+'px';th.style.minWidth=px+'px';(w.columns||(w.columns={}))[index]=px;};const up=()=>{grip.removeEventListener('pointermove',move);grip.removeEventListener('pointerup',up);};grip.addEventListener('pointermove',move);grip.addEventListener('pointerup',up);};th.append(grip);});}
function renderLabTable(list){
 const files=tool==='everything'||tool==='explorer';
 const header=(label,key)=>`<th><button class="sort-button" data-sort="${key}">${label} ${sortKey===key?(sortDirection===1?'↑':'↓'):''}</button></th>`;
 const schemas={downloads:[['Filename','name'],['URL','detail'],['Web Browser','browser'],['Download Start Time','time'],['Full Path','path'],['File Size','size']],history:[['URL','detail'],['Title','name'],['Visit Time','time'],['Web Browser','browser'],['User Profile','user']],activity:[['Action Time','time'],['Description','action'],['Filename','name'],['Full Path','path']],prefetch:[['Filename','action'],['Created Time','time'],['Modified Time','time'],['Last Run Time','time'],['Process EXE','exe'],['Run Counter','runs'],['Files','detail']],usb:[['Device Name','device'],['Description','action'],['Serial Number','serial'],['Last Plug/Unplug Date','time'],['Drive Letter','drive'],['Details','detail']],journaltrace:[['File Name','name'],['Reason','action'],['Timestamp','time'],['Full Path','detail']]};
 const cols=files?[['Name','name'],['Path','folder'],['Size','size'],['Date Modified','time']]:schemas[tool]||[['Time','time'],['Action','action'],['Details','detail']];
 function value(r,key){const a=state.session.artifacts.find(a=>a.id===r.artifact);switch(key){case 'name':return a?.name||r.action;case 'folder':return a?.folder||'';case 'size':return a?.size||'';case 'path':return a?.path||'';case 'time':return time(r.time);case 'browser':return 'Microsoft Edge';case 'user':return state.session.user;case 'exe':return r.action.split('-')[0];case 'runs':return r.detail.match(/Run Counter: (\d+)/)?.[1]||'';case 'device':return 'USB Mass Storage';case 'serial':return 'LAB-'+state.session.seed.toString(16).toUpperCase();case 'drive':return 'E:';default:return r[key]||'';}}
 return `<div class="table-scroll"><table class="${files?'file-grid':'native-data-grid'}"><thead><tr>${cols.map(([label,key])=>header(label,key)).join('')}<th class="training-column">AAC</th></tr></thead><tbody>${list.map(r=>`<tr tabindex="0" data-row="${esc(r.id)}" data-artifact="${r.artifact||''}" class="${r.artifact===selected?'selected':''}">${cols.map(([label,key],i)=>`<td title="${esc(value(r,key))}">${i===0?`<button class="row-open" ${r.artifact?`data-select="${r.artifact}"`:''}><strong>${files?'<span class="file-type-icon">▯</span>':''}${esc(value(r,key))}</strong></button>`:esc(value(r,key))}</td>`).join('')}<td>${r.artifact?`<button class="capture-button" data-capture="${esc(r.id)}" aria-label="Kaydı ekle">+ Kanıt</button>`:''}</td></tr>`).join('')}</tbody></table></div>`;
}
const journalNames={FILE_DELETE:'Deleted',FILE_CREATE:'Created',RENAME_OLD_NAME:'Renamed From',RENAME_NEW_NAME:'Renamed To',CLOSE:'Closed',DATA_OVERWRITE:'Data Changed'};
const journalColors={'Deleted':'#fa3864','Created':'#1ccf8d','Renamed From':'#ff8700','Renamed To':'#e9be00','Closed':'#4c90ff','Data Changed':'#8a78ff'};
function renderJournal(body,list){const filtered=list.filter(r=>!journalFilters.size||journalFilters.has(r.action));const total=filtered.length,pages=Math.max(1,Math.ceil(total/15));journalPage=Math.min(journalPage,pages);const first=(journalPage-1)*15,rows=filtered.slice(first,first+15);body.innerHTML=`<div class="journal-heading">▯ Easy Journal Viewer</div><div class="journal-toolbar"><div class="journal-toggles">${Object.entries(journalNames).map(([id,label])=>`<label><input type="checkbox" data-journal-filter="${id}" ${journalFilters.has(id)?'checked':''}><span style="background:${journalColors[label]}">${label}</span></label>`).join('')}</div><label class="journal-search">⌕ Search <input id="tool-query" value="${esc(query)}" aria-label="Journal Search"></label></div><div class="journal-table-scroll"><table><thead><tr><th>FILE PATH</th><th></th><th>ACTION</th><th><button class="sort-button" data-sort="time">TIMESTAMP ${sortDirection===1?'▲':'▼'}</button></th></tr></thead><tbody>${rows.map(r=>`<tr data-row="${r.id}" data-artifact="${r.artifact||''}" class="${selected===r.artifact?'selected':''}"><td><button class="row-open" data-select="${r.artifact}" title="${esc(r.detail)}">${esc(r.detail)}</button></td><td><button data-open-folder="${r.artifact}" title="Dosya konumunu aç" class="journal-capture">▰</button></td><td><span class="journal-action" style="background:${journalColors[journalNames[r.action]]||'#8a78ff'}">${esc(journalNames[r.action]||r.action)}</span></td><td>${new Date(r.time).toLocaleString('sv-SE')}</td></tr>`).join('')}</tbody></table></div><footer class="journal-footer"><span>Showing ${total?first+1:0} to ${Math.min(first+15,total)} of ${total} entries</span><button class="journal-evidence" data-action="capture-selected">AAC · Seçili kaydı ekle +</button><div><button data-journal-page="${journalPage-1}" ${journalPage===1?'disabled':''}>Previous</button>${Array.from({length:pages},(_,i)=>`<button data-journal-page="${i+1}" class="${journalPage===i+1?'current':''}">${i+1}</button>`).join('')}<button data-journal-page="${journalPage+1}" ${journalPage===pages?'disabled':''}>Next</button></div></footer>`;}
let scanRunning=false,atlasCategory='findings',bookmarks=[];
function atlasHeader(){return `<div class="atlas-actual-header"><img src="assets/atlasac-logo.png" alt="AtlasAC"><strong>AtlasAC</strong><nav><button data-atlas-view="scan" class="${atlasView==='scan'?'active':''}">Tarama</button><button data-atlas-view="results" class="${atlasView==='results'?'active':''}">Sonuçlar</button>${atlasView==='file'?'<button class="active" data-atlas-view="file">Dosya ayrıntısı</button>':''}</nav></div>`;}
function renderAtlas(body,list){let html=atlasHeader();if(atlasView==='scan'){html+=`<section class="atlas-actual-scan"><img src="assets/atlasac-logo.png" alt=""><p>JAR kimlik ve içerik kontrolü · Tam boyut EXE · Süre sınırı yok</p><div><button class="primary" data-action="scan" ${scanRunning?'disabled':''}>Taramayı başlat</button>${scanRunning?'<button class="secondary" data-action="atlas-stop">Durdur</button>':''}</div><span>${scanRunning?'Dosyalar inceleniyor…':scanReady?'Tamamlandı':'Hazır'}</span>${scanRunning?'<progress></progress>':''}<small>Eğitim: yalnız bu oturumun sanal dosya ve kayıtları incelenir.</small></section>`;}else{const all=E.rows(state.session,'atlas'),files=state.session.artifacts.filter(a=>a.status!=='deleted');let items=atlasCategory==='index'?files.map(a=>({id:'index-'+a.id,artifact:a.id,detail:a.path})):list;html+=`<section class="atlas-actual-results"><h2>${scanReady?'Tamamlandı · '+all.length+' eşleşme · '+files.length+' aday':'Henüz tarama yapılmadı.'}</h2><div class="atlas-actual-controls"><select id="atlas-category"><option value="findings" ${atlasCategory==='findings'?'selected':''}>Sonuçlar</option><option value="index" ${atlasCategory==='index'?'selected':''}>Dosya indeksi</option><option value="coverage" ${atlasCategory==='coverage'?'selected':''}>Erişim ve kapsam</option></select><input id="tool-query" value="${esc(query)}" placeholder="Sonuçlarda ara…"><button data-action="atlas-json" ${!scanReady?'disabled':''}>JSON kaydet</button><button data-action="atlas-clear">Yerel verileri sil</button></div>${atlasCategory==='coverage'?'<div class="atlas-coverage"><h3>Eğitim oturumu kapsamı</h3><p>Sanal dosyalar ve oturum kayıtları. Gerçek disk, bellek, sistem kaydı veya gerçek cihaz taranmaz.</p></div>':`<div class="table-scroll"><table class="atlas-result-table"><thead><tr>${['Dosya','Ad','Kural','Yöntem','İz','Açıklama','AAC'].map(x=>'<th>'+x+'</th>').join('')}</tr></thead><tbody>${scanReady?items.filter(r=>!query||[r.detail,state.session.artifacts.find(a=>a.id===r.artifact)?.modId].join(' ').toLowerCase().includes(query.toLowerCase())).map(r=>{const a=state.session.artifacts.find(a=>a.id===r.artifact);return `<tr data-row="${r.id}" data-artifact="${a.id}" class="${selected===a.id?'selected':''}"><td title="${esc(a.path)}"><button class="row-open" data-select="${a.id}">${esc(a.name)}</button></td><td>${esc(a.familyName||a.modId)}</td><td>${atlasCategory==='index'?'—':esc(a.modId)}</td><td>${atlasCategory==='index'?'İndeks':'mod-id'}</td><td>${atlasCategory==='index'?'—':esc("['"+a.modId+"']")}</td><td>Dosya içeriği${a.nested?' · İç arşiv':''}</td><td><button class="capture-button" data-capture="${atlasCategory==='index'?a.id:r.id}">+ Kanıt</button><button class="capture-button" data-open-meta="${a.id}">Ayrıntı</button></td></tr>`;}).join(''):''}</tbody></table></div>`}<p class="atlas-actual-note">Dosya içeriğinde bulunan statik eşleşmeler. Çalıştırma veya oyunda kullanım kanıtı değildir. Sistem izleri kendi kaynak bölümlerindedir.</p></section>`;}html+='<div class="atlas-signature">E.V.</div>';body.innerHTML=html;setupColumns(body);}
function renderApp(){if(tool==='desktop')return;const s=state.session;const family=E.canonical(tool);const list=visibleRows();const body=document.getElementById('app-body');if(tool==='journal'){renderJournal(body,list);return;}if(tool==='atlas'&&atlasView!=='file'){renderAtlas(body,list);return;}let inner=tool==='atlas'?atlasHeader():'';
 if(tool==='explorer')inner=`<div class="path-bar"><button class="text-button" data-action="all-folders">Bu bilgisayar</button><span>›</span><input id="explorer-address" aria-label="Adres" value="${esc(folder||s.home)}"></div><div class="folder-list"><button data-folder="" class="${!folder?'active':''}">Tüm dosyalar</button>${[...new Set(s.artifacts.filter(a=>a.status!=='deleted').map(a=>a.folder))].map(f=>`<button data-folder="${esc(f)}" class="${f===folder?'active':''}" title="${esc(f)}">${esc(f.endsWith('mods')?'Aktif profil / mods':f.split('\\').slice(-2).join(' / '))}</button>`).join('')}</div>`;
 const hints={monitor:'ReadFile gibi dosya erişimlerini işlem adı ve sonuçla karşılaştır. Bir metaveri okuyucunun dosyayı açması, oyunda kullanıldığı anlamına gelmez.',autoruns:'Oturum açılışında çalışan kayıtları, kayıt defteri konumunu ve tam komut satırını incele. Bir girdiyi burada değiştirme; bu ekran salt okunur inceleme içindir.',metadata:'Bir dosya seçerek iç yapısını aç. .jar / .bin uzantısından önce gerçek imzaya ve mod kimliğine bak.',journal:'Dosya hareketlerinin zamanını, eski / yeni adlarını ve silme kayıtlarını karşılaştır.',downloads:'İndirme kaydı bir dosyanın indirildiğini gösterir; oyunda kullanıldığını göstermez.',history:'Sayfa ziyaretlerini indirilen dosya ve zamanlarıyla karşılaştır.',activity:'Etkinlik satırlarını diğer kaynaklarla destekle.',prefetch:'Bir programın çalışma izi, belirli bir modun oyunda kullanıldığını tek başına kanıtlamaz.',usb:'Bağlantı zamanını dosya hareketleriyle karşılaştır. Aynı saate yakın olmak tek başına aktarımı kanıtlamaz.',process:'İşlem adının yanında tam komut satırını incele.',atlas:'İçerik eşleşmelerini doğrula. Tarama sonucu tek başına oyun içi kullanım tespiti değildir.'};
 inner+=`<div class="app-toolbar"><label class="search-box"><span>⌕</span><input id="tool-query" type="search" placeholder="${tool==='explorer'||tool==='everything'?'Dosya adı veya tam yolda ara…':'Kayıtlarda ara…'}" value="${esc(query)}" autocomplete="off" aria-label="${E.tools[tool]} içinde ara"></label><span class="row-count">${list.length} kayıt</span></div>${hints[family]?`<details class="source-hint"><summary>İnceleme notu</summary>${hints[family]}</details>`:''}`;
 if(tool==='atlas'&&atlasView==='file'){const a=s.artifacts.find(a=>a.id===selected);inner+=`<div class="metadata-picker"><label>İçeriğini açacağın dosya<select id="metadata-file"><option value="">Dosya seç…</option>${s.artifacts.filter(a=>a.status!=='deleted'&&(!query||[a.name,a.path,a.modId].join(' ').toLocaleLowerCase('tr-TR').includes(query.toLocaleLowerCase('tr-TR')))).map(a=>`<option value="${a.id}" ${a.id===selected?'selected':''}>${esc(a.name)} · ${esc(a.folder)}</option>`).join('')}</select></label></div>`;if(a&&a.status!=='deleted'){inner+=`<div class="metadata-content"><div class="metadata-head"><div><span class="eyebrow">DOSYA İÇERİĞİ</span><h2>${esc(a.name)}</h2></div><button class="secondary compact" data-capture="metadata-${a.id}">Kanıt defterine ekle +</button></div><dl><dt>Tam yol</dt><dd>${esc(a.path)}</dd><dt>Gerçek imza</dt><dd>${a.kind==='PE / DLL'?'4D 5A · MZ / PE':'50 4B 03 04 · ZIP / JAR'}</dd><dt>SHA-256 (eğitim değeri)</dt><dd class="hash">${a.hash}</dd><dt>Dosya boyutu</dt><dd>${a.size}</dd></dl>${a.nested?`<div class="archive-chain">${esc(a.name)} <span>› extras.zip › ${esc(a.modId)}.jar › fabric.mod.json</span></div>`:''}${tool==='atlas'&&atlasView==='file'?`<div class="archive-tree"><strong>Arşiv ağacı</strong><button data-archive-entry="metadata">${a.nested?'extras.zip / '+esc(a.modId)+'.jar / ':''}fabric.mod.json</button><button data-archive-entry="manifest">META-INF / MANIFEST.MF</button>${a.mixed?'<button data-archive-entry="clean">fabric-api.jar / fabric.mod.json</button>':''}</div>`:''}<pre id="archive-content" data-mod-id="${esc(a.modId)}">${esc(a.kind==='PE / DLL'?'ProductName: Mesa OpenGL\nFileType: Graphics compatibility library':JSON.stringify({schemaVersion:1,id:a.modId,environment:'client',name:a.familyName||a.modId,depends:{minecraft:a.minecraft||'Eğitim örneğinde belirtilmedi'}},null,2))}</pre><p class="micro">Bu içerik ve hash, eğitim oturumu için üretilmiştir; gerçek dosya doğrulaması değildir.</p></div>`;}else inner+='<div class="empty-state">Bir dosya seçerek içeriğini incele.</div>';
 }else {inner+=tool==='everything'?`<div class="everything-filter"><label>Filter: <select id="native-extension"><option value="">Everything</option><option value="jar" ${query==='ext:jar'?'selected':''}>JAR files</option><option value="exe" ${query==='ext:exe'?'selected':''}>Executables</option><option value="zip" ${query==='ext:zip'?'selected':''}>Archives</option></select></label><button class="text-button" data-action="export-csv">Export…</button></div>`:`<div class="record-filters"><label>İşlem <select id="record-type"><option value="">Tümü</option>${[...new Set(E.rows(s,tool).map(r=>r.action))].map(action=>`<option value="${esc(action)}" ${recordType===action?'selected':''}>${esc(action)}</option>`).join('')}</select></label><label>Zaman <select id="record-time"><option value="all">Tümü</option><option value="1" ${timeRange==='1'?'selected':''}>Son 1 saat</option><option value="24" ${timeRange==='24'?'selected':''}>Son 24 saat</option></select></label><button class="text-button" data-action="export-csv">CSV dışa aktar ↓</button></div>`;inner+=list.length?renderLabTable(list):'<div class="empty-state">Bu kaynakta aramana uygun kayıt yok. Başka bir sözcük veya araç dene.</div>';}
 if(selected){const a=s.artifacts.find(a=>a.id===selected);inner+=`<div class="file-inspector"><div><span class="eyebrow">SEÇİLİ DOSYA</span><strong>${esc(a.name)}</strong><code>${esc(a.path)}</code></div><div class="inspector-actions"><button class="secondary compact" data-open-meta="${a.id}">İçeriği aç</button><button class="secondary compact" data-action="notes">Notlarım ↗</button></div></div>`;}
 body.innerHTML=inner;setupColumns(body);const count=body.closest('.app-window')?.querySelector('.native-status span');if(count)count.textContent=list.length+' nesne'+(selected?' · 1 seçili':'');
}
function renderNotes(){const host=document.getElementById('note-body');if(!host)return;const s=state.session;const recorded=Object.keys(state.notes);if(!selected&&!recorded.length){host.innerHTML='<div class="empty-notes"><span>+</span><h3>Henüz bulgu eklemedin.</h3><p>Bir kaydın yanındaki “Kanıt” düğmesine basarak başla.</p></div>';return;}if(!selected)selected=recorded[0];const a=s.artifacts.find(a=>a.id===selected);if(!a)return;const n=state.notes[a.id]||{evidence:[],verdict:'',usage:'',comment:''};host.innerHTML=`<div class="note-tabs">${recorded.map(id=>`<button class="${id===selected?'active':''}" data-select="${id}">${esc(s.artifacts.find(a=>a.id===id)?.name)}</button>`).join('')}</div><h3 class="note-name">${esc(a.name)}</h3><code class="note-path">${esc(a.path)}</code><div class="evidence-label">TOPLANAN KAYNAKLAR <b>${n.evidence.length}</b></div><div class="evidence-list">${n.evidence.map((e,i)=>`<article><div><b>${esc(E.tools[e.source]||'AtlasAC · Dosya içeriği')}</b><button data-remove-evidence="${i}" aria-label="Bu kanıtı kaldır">✕</button></div><p>${esc(e.text)}</p></article>`).join('')||'<p class="micro">Bu dosya için henüz kaynak eklenmedi.</p>'}</div><label class="note-label">Bulgunun durumu<select id="note-verdict"><option value="">Henüz karar vermedim</option>${Object.entries(E.verdicts).map(([v,label])=>`<option value="${v}" ${n.verdict===v?'selected':''}>${label}</option>`).join('')}</select></label><label class="note-label">Oyun içi kullanım hakkında<select id="note-usage"><option value="">Seç…</option><option value="unproven" ${n.usage==='unproven'?'selected':''}>Bu bulgular tek başına kullanım kanıtlamaz</option><option value="proven" ${n.usage==='proven'?'selected':''}>Oyunda kullanıldığını kanıtlar</option></select></label><label class="note-label">Gerekçen<textarea id="note-comment" rows="4" placeholder="Hangi kaynağı neyle ilişkilendirdin?">${esc(n.comment)}</textarea></label><p class="micro">Kaynak ve sınıflandırmalar puanlanır. Serbest açıklaman öz değerlendirme / mülakat sunumu içindir; anahtar kelime sayılarak puan verilmez.</p>`;}
function capture(key){let artifact,text,source=tool;if(key.startsWith('metadata-')){artifact=key.slice(9);const a=state.session.artifacts.find(a=>a.id===artifact);const opened=document.getElementById('archive-content');source=opened?.dataset.modId===a.modId?'metadata':'archive';text=a.path+' · '+a.kind+' · '+(source==='metadata'?'id='+a.modId:opened?.textContent||'Arşiv girdisi')+(a.nested?' · İç arşiv girdisi':'');}else{const r=tool==='atlas'&&atlasCategory==='index'?E.rows(state.session,'explorer').find(r=>r.id===key):visibleRows().find(r=>r.id===key);if(!r)return;if(tool==='atlas'&&atlasCategory==='index')source='explorer';artifact=r.artifact;text=r.action+' · '+r.detail+' · '+time(r.time);}if(!artifact)return;selected=artifact;const n=note(artifact);if(!n.evidence.some(e=>e.key===key&&e.source===source)){n.evidence.push({key,source,text});save();toast('Kanıt defterine eklendi.');}else toast('Bu kaynak zaten defterinde.');renderApp();renderNotes();}
function showDialog(title,body,actions){let d=document.getElementById('lab-dialog');if(d)d.remove();d=document.createElement('dialog');d.id='lab-dialog';d.innerHTML=`<h2>${title}</h2>${body}<div class="dialog-actions">${actions}</div>`;root.append(d);d.showModal();}
function results(){clearInterval(timer);const s=state.session,r=E.evaluate(s,state.notes);root.innerHTML=`<main class="results"><a href="../#home" target="_top" class="back-link">← AAC Wiki</a><div class="results-heading"><div><span class="eyebrow">${s.id} · MÜLAKAT TAMAMLANDI</span><h1>Kontrolün sonuçları.</h1><p>Yalnız bulduğun dosyalar değil, onları nasıl doğruladığın da önemli.</p></div><div class="score"><strong>${r.score}</strong><span>/ 100</span></div></div><div class="result-stats"><article><strong>${r.identified}/${r.total}</strong><span>İçerikle doğrulanmış doğru sınıflandırma</span></article><article><strong>${r.falsePositives}</strong><span>Temiz dosyada yanlış işaretleme</span></article><article><strong>${Math.floor((state.endedAt-s.startedAt)/60000)} dk</strong><span>İnceleme süresi</span></article></div><p class="results-note">Bu oturumda ${r.suspicious} şüpheli iz ve ${r.total-r.suspicious} temiz / yanıltıcı örnek vardı. Puanlama: sınıflandırma %35, içerik %25, konum %15, destekleyen kayıt %15, kullanım iddiasını ayırma %10. Serbest gerekçen otomatik puanlanmaz.</p><section class="result-list">${r.items.map(item=>{const n=state.notes[item.id]||{};return `<details class="result-item" ${item.points<80?'open':''}><summary><span class="result-status ${item.points>=80?'good':'miss'}">${item.points>=80?'✓':'↗'}</span><span><strong>${esc(item.name)}</strong><small>${esc(E.verdicts[item.expected])}</small></span><b>${item.points}/100</b></summary><div class="result-content"><code>${esc(item.path)}</code>${item.caseId?`<p class="case-reveal"><strong>${esc(item.caseId)}</strong> · ${esc(item.caseTitle)}</p>`:''}<p><strong>Senin sınıflandırman:</strong> ${esc(E.verdicts[item.chosen]||'İşaretlenmedi')}</p><div class="rubric">${[['Sınıflandırma',item.classification],['İçerik / silme kaydı',item.content],['Konum',item.location],['Destekleyen kaynak',item.support],['Kullanım ayrımı',item.cautious]].map(([label,ok])=>`<span class="${ok?'ok':'missing'}">${ok?'✓':'○'} ${label}</span>`).join('')}</div><p>${esc(item.explanation)}</p>${n.comment?`<blockquote><strong>Notun:</strong> ${esc(n.comment)}</blockquote>`:''}</div></details>`;}).join('')}</section><div class="result-actions"><button class="primary" data-action="new-prompt">Yeni rastgele mülakat ↗</button><button class="secondary" data-action="export">Raporu indir</button><a class="secondary" href="../#process" target="_top">Kontrol rehberini tekrar incele</a></div><p class="privacy-note">Bu puan alıştırma sonucudur; sertifika veya resmî yetkinlik kararı değildir.</p></main>`;}
root.addEventListener('input',e=>{if(e.target.id==='tool-query'){const start=e.target.selectionStart;query=e.target.value;renderApp();const input=document.getElementById('tool-query');input.focus();try{input.setSelectionRange(start,start);}catch{}}if(e.target.id==='note-comment'){note(selected).comment=e.target.value;save();}});
root.addEventListener('change',e=>{if(e.target.id==='native-extension'){query=e.target.value?'ext:'+e.target.value:'';renderApp();}if(e.target.id==='atlas-permission')document.querySelector('[data-action=atlas-scan-confirm]').disabled=!e.target.checked;if(e.target.id==='atlas-category'){atlasCategory=e.target.value;renderApp();}if(e.target.dataset.journalFilter){if(e.target.checked)journalFilters.add(e.target.dataset.journalFilter);else journalFilters.delete(e.target.dataset.journalFilter);journalPage=1;renderApp();}if(e.target.id==='record-type'){recordType=e.target.value;renderApp();}if(e.target.id==='record-time'){timeRange=e.target.value;renderApp();}if(e.target.id==='metadata-file'){selected=e.target.value||null;renderApp();renderNotes();}if(e.target.id==='note-verdict'){note(selected).verdict=e.target.value;save();}if(e.target.id==='note-usage'){note(selected).usage=e.target.value;save();}});
root.addEventListener('click',async e=>{const t=e.target.closest('button');if(!t)return;
 if(t.dataset.journalPage){journalPage=Number(t.dataset.journalPage);renderApp();return;}
 if(t.dataset.tool){startOpen=false;document.querySelector('.start-menu')?.setAttribute('hidden','');document.getElementById('lab-dialog')?.close();openWindow(t.dataset.tool);return;}
 if('folder'in t.dataset){folder=t.dataset.folder;query='';renderApp();return;}
 if(t.dataset.atlasView){atlasView=t.dataset.atlasView;query='';renderApp();return;}
 if(t.dataset.archiveEntry){const a=state.session.artifacts.find(a=>a.id===selected);const pane=document.getElementById('archive-content'),entry=t.dataset.archiveEntry;pane.dataset.modId=entry==='metadata'?a.modId:entry==='clean'?'fabric-api':'';pane.textContent=entry==='manifest'?'Manifest-Version: 1.0\nCreated-By: Atlas Lab eğitim üreticisi':JSON.stringify({schemaVersion:1,id:entry==='clean'?'fabric-api':a.modId,environment:'client',name:entry==='clean'?'Fabric API':a.modId},null,2);return;}
 if(t.dataset.sort){sortDirection=sortKey===t.dataset.sort?-sortDirection:1;sortKey=t.dataset.sort;renderApp();return;}
 if(t.dataset.select){selected=t.dataset.select;renderApp();renderNotes();return;}
 if(t.dataset.capture){capture(t.dataset.capture);return;}
 if(t.dataset.openFolder){const a=state.session.artifacts.find(a=>a.id===t.dataset.openFolder);if(a){openWindow('explorer');folder=a.folder;query='';selected=a.id;renderApp();}return;}
 if(t.dataset.openMeta){selected=t.dataset.openMeta;openWindow('atlas');selected=t.dataset.openMeta;atlasView='file';query='';renderApp();renderNotes();return;}
 if('removeEvidence'in t.dataset){note(selected).evidence.splice(Number(t.dataset.removeEvidence),1);save();renderNotes();return;}
 const action=t.dataset.action;
 if(action==='new'){create();return;}
 if(action==='resume'){render();return;}
 if(action==='new-prompt'){showDialog('Yeni bir ortam oluşturulsun mu?','<p>Yeni oturumda oyuncu, dosya adları, konumlar ve kayıt zinciri değişir. Önceki sonucu saklamak istersen raporunu indir.</p>','<button class="secondary" data-action="close-dialog">Vazgeç</button><button class="primary" data-action="new">Yeni oturum oluştur</button>');return;}
 if(action==='apps-folder'){showDialog('AAC Uygulamalar',`<div class="application-folder">${toolNav()}</div>`,'<button class="secondary" data-action="close-dialog">Kapat</button>');return;}
 if(action==='brief'){showDialog('Görevin',`<p>Oyuncunun dosyalarını ve sistem kayıtlarını incele. Şüpheli ve temiz bulguları birbirinden ayır; her kararını kaynaklarla destekle.</p><p>Oyuncu: <strong>${esc(state.session.nick)}</strong><br>Aktif oyun dizini: <code class="brief-path">${esc(state.session.game)}</code></p><ul><li>Aktif profilin tam dizini sol altta.</li><li>Arşivlerin içeriğini AtlasAC dosya incelemesiyle aç.</li><li>Silinmiş izi mevcut dosya gibi değerlendirme.</li><li>Dosya varlığı, yüklenme ve oyun içi kullanım farklı şeylerdir.</li></ul><p>Önerilen süre 25 dakika. Süre dolsa da mülakatı kendin bitirene kadar inceleyebilirsin.</p>`,'<button class="primary" data-action="close-dialog">İncelemeye dön</button>');return;}
 if(action==='finish-prompt'){const count=Object.values(state.notes).filter(n=>n.verdict).length;showDialog('Mülakatı tamamla',`<p>${count} bulgu için sınıflandırma yaptın. Bitirdiğinde cevaplar ve eksik kanıtların açılır; bu oturumdaki yanıtların kilitlenir.</p>`,'<button class="secondary" data-action="close-dialog">İncelemeye dön</button><button class="primary" data-action="finish">Bitir ve değerlendirmeyi gör</button>');return;}
 if(action==='finish'){state.finished=true;state.endedAt=Date.now();save();render();return;}
 if(action==='close-dialog'){document.getElementById('lab-dialog')?.close();return;}
 if(action==='scan'){showDialog('AtlasAC · Tarama öncesi bilgilendirme','<p>Bu eğitim oturumunun sanal dosyaları içerik ve kimlik açısından incelenecek. Cihazındaki gerçek dosyalara erişilmez.</p><label class="atlas-consent"><input id="atlas-permission" type="checkbox"> Bu eğitim ortamındaki incelemeyi başlatmak istiyorum.</label>','<button class="secondary compact" data-action="close-dialog">Vazgeç</button><button class="primary compact" data-action="atlas-scan-confirm" disabled>Taramayı başlat</button>');return;}
 if(action==='atlas-scan-confirm'){document.getElementById('lab-dialog').close();const current=state.session.id;scanRunning=true;scanReady=false;atlasView='scan';renderApp();setTimeout(()=>{if(state?.session.id!==current||state.finished||!scanRunning)return;scanRunning=false;scanReady=true;const w=windows.get('atlas');if(w)w.atlasView='results';if(tool==='atlas'){atlasView='results';renderApp();}},2400);return;}
 if(action==='atlas-stop'){scanRunning=false;scanReady=false;renderApp();return;}
 if(action==='atlas-clear'){scanRunning=false;scanReady=false;atlasView='scan';renderApp();toast('AtlasAC eğitim tarama verisi silindi. Kanıt defterin korundu.');return;}
 if(action==='atlas-json'){const rows=E.rows(state.session,'atlas');const blob=new Blob([JSON.stringify({type:'AtlasAC eğitim taraması',session:state.session.id,findings:rows},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=state.session.id+'-atlasac.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);return;}
 if(action==='all-folders'){folder='';query='';renderApp();return;}
 if(action==='notes'){toggleNotes(true);return;}
 if(action==='notes-close'){toggleNotes(false);return;}
 if(action==='start-menu'){startOpen=!startOpen;document.querySelector('.start-menu').hidden=!startOpen;if(startOpen)document.getElementById('start-search').focus();t.setAttribute('aria-expanded',String(startOpen));return;}
 if(action==='minimize-window'||action==='close-window'){const w=windows.get(activeWindow);if(w){if(action==='close-window'){w.el.remove();windows.delete(activeWindow);}else w.el.hidden=true;}activeWindow=null;tool='desktop';renderTaskbar();return;}
 if(action==='maximize-window'){windows.get(activeWindow)?.el.classList.toggle('window-maximized');return;}
 if(action==='desktop'){storeWindow();windows.forEach(w=>w.el.hidden=true);activeWindow=null;tool='desktop';renderTaskbar();return;}
 if(action==='fullscreen'){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Tam ekran için laboratuvarı ayrı sekmede açabilirsin.');}return;}
 if(action==='export-csv'){const rows=[['Zaman','İşlem','Kayıt'],...visibleRows().map(r=>[r.time,r.action,r.detail])];const csv='\uFEFF'+rows.map(row=>row.map(value=>'"'+String(value).replace(/^[=+@-]/,"'").replaceAll('"','""')+'"').join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=state.session.id+'-'+tool+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);return;}
 if(action==='export'){const report={type:'Atlas AAC eğitim simülasyonu',sessionId:state.session.id,player:state.session.nick,startedAt:new Date(state.session.startedAt).toISOString(),endedAt:new Date(state.endedAt).toISOString(),result:E.evaluate(state.session,state.notes),notes:state.notes};const url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=state.session.id+'-rapor.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
});
// Windows-style focus, moving, resizing and keyboard behavior.
root.addEventListener('pointerdown',e=>{const win=e.target.closest('[data-window]');if(!win)return;const id=win.dataset.window;if(activeWindow!==id)focusWindow(id);const title=e.target.closest('.window-title');if(!title||e.target.closest('button')||win.classList.contains('window-maximized')||!e.isTrusted)return;const rect=win.getBoundingClientRect(),x=e.clientX,y=e.clientY;title.setPointerCapture(e.pointerId);const move=ev=>{win.style.left=Math.max(0,Math.min(innerWidth-160,rect.left+ev.clientX-x))+'px';win.style.top=Math.max(0,Math.min(innerHeight-90,rect.top+ev.clientY-y))+'px';};const up=()=>{title.removeEventListener('pointermove',move);title.removeEventListener('pointerup',up);title.removeEventListener('pointercancel',up);};title.addEventListener('pointermove',move);title.addEventListener('pointerup',up);title.addEventListener('pointercancel',up);},true);
root.addEventListener('dblclick',e=>{if(e.target.closest('.window-title')&&!e.target.closest('button'))windows.get(activeWindow)?.el.classList.toggle('window-maximized');});
root.addEventListener('input',e=>{if(e.target.id==='start-search'){const q=e.target.value.toLocaleLowerCase('tr');document.querySelectorAll('.start-apps [data-tool]').forEach(b=>b.hidden=!b.textContent.toLocaleLowerCase('tr').includes(q));}});
function runDialog(){showDialog('Çalıştır','<div class="run-content"><p>Bir program veya klasör adı yazın; Windows eğitim ortamında açılacaktır.</p><label>Aç: <input id="run-command" autocomplete="off" autofocus placeholder="everything, explorer, %appdata%…"></label><p class="micro">Bu komutlar eğitim masaüstündeki uygulamalara yönlendirilir.</p></div>','<button class="primary compact" data-action="run-confirm">Tamam</button><button class="secondary compact" data-action="close-dialog">İptal</button>');setTimeout(()=>document.getElementById('run-command')?.focus(),0);}
function runCommand(){const v=document.getElementById('run-command').value.trim().toLowerCase().replace(/\.exe$/,'');const aliases={'journal-tool':'journal','browserdownloadsview':'downloads','browsinghistoryview':'history','lastactivityview':'activity','usbdeview':'usb','winprefetchview':'prefetch','atlasac':'atlas','explorer':'explorer'};const id=aliases[v]||Object.keys(E.tools).find(id=>id===v||E.tools[id].toLowerCase()===v);if(id){document.getElementById('lab-dialog').close();openWindow(id);}else if(v.includes('appdata')||v.includes('downloads')||v.startsWith('c:')){document.getElementById('lab-dialog').close();openWindow('explorer');folder='';query=v.includes('appdata')?'AppData':v;renderApp();}else toast('Bu eğitim ortamında bu komut bulunamadı. Everything veya explorer yazabilirsin.');}
root.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.action==='run')runDialog();if(t.dataset.action==='run-confirm')runCommand();if(t.dataset.nativeMenu){document.getElementById('native-popup')?.remove();const popup=document.createElement('div');popup.id='native-popup';popup.className='native-popup';const menuAliases={File:'Dosya',Edit:'Düzen',View:'Görünüm',Search:'Ara',Bookmarks:'Yer İmleri',Tools:'Araçlar',Options:'Araçlar',Help:'Yardım'};const menus={Dosya:[['İçeriği aç','open-selected'],['Özellikler','properties'],['CSV dışa aktar','export-csv'],['Kapat','close-window']],Düzen:[['Tam yolu kopyala','copy-path'],['Kanıt defterine ekle','capture-selected']],Görünüm:[['Ayrıntılar','details'],['Gizli dosyaları göster / gizle','toggle-hidden'],['Yenile','refresh-app']],Araçlar:[['Çalıştır…','run'],['Kanıt defteri','notes']],Ara:[['Aramaya odaklan','focus-search'],['Tüm dosyalar','clear-search'],['JAR dosyaları','search-jar']], 'Yer İmleri':[['Geçerli aramayı kaydet','bookmark-add'],...bookmarks.map((q,i)=>[q,'bookmark-'+i])],Yardım:[['Uygulama hakkında','about-app'],['Görev bilgisi','brief']]};popup.innerHTML=menus[menuAliases[t.dataset.nativeMenu]||t.dataset.nativeMenu].map(([text,action])=>`<button data-action="${action}">${text}</button>`).join('');t.closest('.app-window').append(popup);const r=t.getBoundingClientRect(),wr=t.closest('.app-window').getBoundingClientRect();popup.style.left=(r.left-wr.left)+'px';popup.style.top=(r.bottom-wr.top)+'px';}
const action=t.dataset.action;
if(action==='focus-search')document.getElementById('tool-query')?.focus();
if(action==='clear-search'||action==='search-jar'){query=action==='search-jar'?'ext:jar':'';renderApp();}
if(action==='bookmark-add'){if(query&&!bookmarks.includes(query)){bookmarks.push(query);toast('Arama yer imlerine eklendi.');}else toast('Önce kaydetmek istediğin aramayı yaz.');}
if(action?.startsWith('bookmark-')&&action!=='bookmark-add'){query=bookmarks[Number(action.slice(9))]||'';renderApp();}
if(action==='refresh-app'||action==='details')renderApp();
if(action==='toggle-hidden'){showHidden=!showHidden;renderApp();toast(showHidden?'Gizli dosyalar gösteriliyor.':'Gizli dosyalar gizlendi.');}
if(action==='about-app')showDialog(E.tools[tool],`<p>${E.tools[tool]} arayüzünün eğitim uyarlaması. Orijinal uygulama simgesi kullanılır. Uygulama bu mülakatın sanal dosya ve kayıtlarında işlem yapar.</p>`,'<button class="primary compact" data-action="close-dialog">Tamam</button>');
if(action==='copy-path'){const a=state.session.artifacts.find(a=>a.id===selected);if(a)navigator.clipboard?.writeText(a.path).then(()=>toast('Tam yol kopyalandı.')).catch(()=>toast(a.path));else toast('Önce bir dosya seç.');}
if(action==='capture-selected'){const row=visibleRows().find(r=>r.artifact===selected);if(row)capture(row.id);else toast('Önce bir kayıt seç.');}
if(action==='open-selected'){const a=state.session.artifacts.find(a=>a.id===selected);if(a){openWindow('atlas');selected=a.id;atlasView='file';renderApp();}else toast('Önce bir dosya seç.');}
if(action==='properties'){const a=state.session.artifacts.find(a=>a.id===selected);if(a)showDialog(a.name+' · Özellikler',`<dl class="file-properties"><dt>Tür</dt><dd>${esc(a.kind)}</dd><dt>Konum</dt><dd>${esc(a.folder)}</dd><dt>Boyut</dt><dd>${esc(a.size)}</dd><dt>Öznitelikler</dt><dd>${a.hidden?'Gizli, Arşiv':'Arşiv'}</dd></dl>`,'<button class="primary compact" data-action="close-dialog">Tamam</button>');else toast('Önce bir dosya seç.');}
if(action&&!t.closest('.native-menubar'))document.getElementById('native-popup')?.remove();
});
document.addEventListener('keydown',e=>{if(!state||state.finished)return;if(e.key==='Escape'){document.getElementById('native-popup')?.remove();document.querySelector('.start-menu')?.setAttribute('hidden','');startOpen=false;toggleNotes(false);}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='r'){e.preventDefault();runDialog();}if(e.key==='Enter'&&e.target.id==='explorer-address'){e.preventDefault();const path=e.target.value.trim().replace(/\\$/,'');folder=state.session.artifacts.some(a=>a.folder.toLowerCase()===path.toLowerCase())?state.session.artifacts.find(a=>a.folder.toLowerCase()===path.toLowerCase()).folder:'';query=folder?'':path.length>3?path:'';renderApp();}if(e.key==='Enter'&&e.target.id==='run-command'){e.preventDefault();runCommand();}if(e.key==='F5'&&activeWindow){e.preventDefault();renderApp();}if((e.ctrlKey&&e.key==='f')||(e.key==='F3')){const input=document.getElementById('tool-query');if(input){e.preventDefault();input.focus();input.select();}}if(e.altKey&&e.key==='F4'&&activeWindow){e.preventDefault();windows.get(activeWindow).el.querySelector('[data-action=close-window]').click();}});
root.addEventListener('click',e=>{const row=e.target.closest('[data-row]');if(row&&!e.target.closest('button')&&row.dataset.artifact){selected=row.dataset.artifact;renderApp();renderNotes();}});
root.addEventListener('dblclick',e=>{const row=e.target.closest('[data-row]');if(row?.dataset.artifact){const id=row.dataset.artifact;openWindow('atlas');selected=id;atlasView='file';renderApp();renderNotes();}});
root.addEventListener('contextmenu',e=>{const row=e.target.closest('[data-row]');if(row?.dataset.artifact){e.preventDefault();selected=row.dataset.artifact;renderNotes();windows.get(activeWindow)?.el.querySelector('[data-native-menu="File"]')?.click();}});
document.addEventListener('keydown',e=>{if(!state||state.finished||!activeWindow||e.target.matches('input,textarea,select'))return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){const rows=visibleRows().filter(r=>r.artifact);let i=rows.findIndex(r=>r.artifact===selected);i=Math.max(0,Math.min(rows.length-1,i+(e.key==='ArrowDown'?1:-1)));if(rows[i]){e.preventDefault();selected=rows[i].artifact;renderApp();renderNotes();windows.get(activeWindow).el.querySelector('tr.selected')?.scrollIntoView({block:'nearest'});}}if(e.key==='Enter'&&selected){e.preventDefault();const id=selected;openWindow('atlas');selected=id;atlasView='file';renderApp();}});
welcome();
})();
